/* DotCC cursors are scoped ref-like values, rather than a native array ABI.
 * Keep the exact copy/end/format operations with a direct local cursor; native
 * controls retain the upstream array-portability wrapper. */
#if defined(S2N_DOTCC_MANAGED_PROVIDER)
#define S2N_VA_LIST_TYPE va_list
#define S2N_VA_LIST_VALUE(value) (value)
static void s2n_va_list_cleanup(va_list *list)
{
    if (list != NULL) {
        va_end(*list);
    }
}
#else
#define S2N_VA_LIST_TYPE struct s2n_va_list
#define S2N_VA_LIST_VALUE(value) ((value).va_list)
struct s2n_va_list {
    va_list va_list;
};

static void s2n_va_list_cleanup(struct s2n_va_list *list)
{
    if (list) {
        va_end(list->va_list);
    }
}
